public static METSalesOrderExtractionExportIntegration construct()
{
    return new METSalesOrderExtractionExportIntegration();
}

boolean isNeedToCreateLog(METSalesOrderExtractionTable  _salesOrderExtractionTable)
{
    boolean                             res;
    ;
    if (this.isMessageTypeEnabled() &&
        _salesOrderExtractionTable.ExtractionStatus == METSalesOrderExtractionStatus::Completed
        )
    {
        res = true;
        if (DEVIntegExportDocumentLog::sentRecordExists(_salesOrderExtractionTable, messageTypeTableOutbound.ClassName))  //already marked to send
        {
            res = false;
        }
    }
    return res;
}

public boolean insertFromMETSalesOrderExtractionTable(METSalesOrderExtractionTable  _salesOrderExtractionTable)
{
    boolean  res;
    ;
    if(this.isNeedToCreateLog(_salesOrderExtractionTable))
    {
        this.createLogFromCommon(_salesOrderExtractionTable, _salesOrderExtractionTable.ExtractionId);
        res = true;
    }
    return res;
}

[DataEventHandler(tableStr(METSalesOrderExtractionTable), DataEventType::Updated)]
public static void METSalesOrderExtractionTable_onUpdated(Common sender, DataEventArgs e)
{
    METSalesOrderExtractionTable salesOrderExtractionTable = sender as METSalesOrderExtractionTable;
    if (salesOrderExtractionTable.orig().ExtractionStatus != METSalesOrderExtractionStatus::Completed &&
        salesOrderExtractionTable.ExtractionStatus == METSalesOrderExtractionStatus::Completed)
    {
        METSalesOrderExtractionExportIntegration  exportMessage = METSalesOrderExtractionExportIntegration::construct();
        exportMessage.insertFromMETSalesOrderExtractionTable(salesOrderExtractionTable);
    }
}

public void exportAllData()
{
    Query                        query = new Query();
    QueryBuildDataSource         qBDS;
    METSalesOrderExtractionTable salesOrderExtractionTable;
    int                          processedCounter, insertCounter;

    qBDS = query.addDataSource(tableNum(METSalesOrderExtractionTable));
    qBDS.addRange(fieldNum(METSalesOrderExtractionTable, ExtractionStatus)).value(SysQuery::value(METSalesOrderExtractionStatus::Completed));
    qBDS = qBDS.addDataSource(tableNum(METSalesOrderExtractionLine));
    qBDS.joinMode(JoinMode::ExistsJoin);
    qBDS.relations(true);
    QueryRun     queryRun;
    queryRun = new QueryRun(query);
    if (queryRun.prompt())
    {
        while (queryRun.next())
        {
            salesOrderExtractionTable = queryRun.get(tableNum(METSalesOrderExtractionTable));
            if (this.insertFromMETSalesOrderExtractionTable(salesOrderExtractionTable))
            {
                insertCounter++;
            }
            processedCounter++;
        }
        info(strfmt("%1 record(s) processed, %2 marked to export", processedCounter, insertCounter));
    }
}

public str getDescription()
{
    return "Metcash - Sales order extraction export to Dallas";
}

/// <summary>
/// Builds the Dallas export CSV of direct picklist rows.
/// </summary>
/// <param name = "_exportDocumentLog">Export document log identifying the extraction to export</param>
/// <returns>CSV content as a memory stream</returns>
public System.IO.MemoryStream generateDataStream(DEVIntegExportDocumentLog _exportDocumentLog)
{
    DEVFileWriterCSV                csvWriter = new DEVFileWriterCSV();
    METSalesOrderExtractionLine     extractionLine;
    METWMSPicklistEntity            pickListEntity;
    str                             extractionId = _exportDocumentLog.DocumentId;

    csvWriter.init(messageTypeTableOutbound.getFileColumnDelimiter());

    csvWriter.addContainerLine([
        'Customer',
        'CutOffDay',
        'CutOffTime',
        'DeliveryInstructions',
        'DispatchDay',
        'DispatchTime',
        'ItemId',
        'LineNum',
        'LotId',
        'OrderDate',
        'OrderNumber',
        'OrderType',
        'PicklistNumber',
        'Route',
        'RouteStop',
        'ShippingDate',
        'ShippingSite',
        'ShippingWarehouse',
        'StagingLane',
        'Volume',
        'Weight',
        'WMSOrderTransRecId',
        'WMSOrderType',
        'CWItem',
        'CommodityCode',
        'Door',
        'expeditionStatus',
        'METPickedQtyProcessed',
        'METPickedQtyUpdated',
        'InternalCustomer',
        'METPickedCases',
        'METPickedBrokenCases',
        'UnitShipCaseQty',
        'BondedWarehouse',
        'InternalCustPaymMethod',
        'PickEaches',
        'ReservedQty',
        'PdsCWConversion',
        'CaseUOM'
    ]);

    while select pickListEntity
        exists join extractionLine
            where extractionLine.ExtractionId == extractionId
               && extractionLine.SalesId      == pickListEntity.OrderNumber
    {
        this.addPicklistEntityLine(csvWriter, pickListEntity);
    }

    return csvWriter.getCSVStream();
}

public void exportFileMessage(DEVIntegExportDocumentLog _exportDocumentLog, DEVIntegMessagesLoadBaseType _loadFileStorageCache)
{
    System.IO.MemoryStream  memoryStream;
    str                     extractionId = _exportDocumentLog.DocumentId;
    FileName                fileName;

    memoryStream = this.generateDataStream(_exportDocumentLog);

    fileName = messageTypeTableOutbound.getFileName(DateTimeUtil::utcNow(), _exportDocumentLog);
    this.sendMessageFileStorageCache(_exportDocumentLog, _loadFileStorageCache, fileName, memoryStream);

    // Data modification: skip when previewType is PreviewOnly.
    if (this.parmPreviewType() != DEVIntegMessagesPreviewType::PreviewOnly)
    {
        this.updateExportStatus(extractionId);
    }
}

protected void updateExportStatus(METSalesOrderExtractionId _extractionId)
{
    METSalesOrderExtractionTable header;

    ttsbegin;
    header = METSalesOrderExtractionTable::find(_extractionId, true);
    if (header.RecId)
    {
        header.Exported         = NoYes::Yes;
        header.ExportedDateTime = DateTimeUtil::utcNow();
        header.update();
    }
    ttscommit;
}
